scripts.campaign-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'campaign-store',
  description:
    "Read and update the campaign room: the campaign (campaign.json), its assets (assets.json) and its results and spend (results.json). action:'status' for the whole picture; 'set_campaign' for the goal, audience, dates and budget (budgetChange adds to the budget); 'add_asset' to plan an asset (an existing title is updated, never duplicated); 'move_asset' to change an asset's stage, date or owner; 'log_result' for an asset's numbers on a day; 'log_spend' for money spent; 'list' for every asset.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'set_campaign', 'add_asset', 'move_asset', 'log_result', 'log_spend', or 'list'.",
      required: true,
    },
    name: { type: 'string', description: "The campaign's name, e.g. 'The Salt Road launch'." },
    goal: { type: 'string', description: "The goal in the person's words, e.g. '600 preorders by launch day'." },
    audience: { type: 'string', description: 'Who the campaign is for.' },
    goalMetric: { type: 'string', description: "What the goal counts, e.g. 'preorders', 'signups', 'bookings'." },
    goalTarget: { type: 'number', description: 'The number to reach, e.g. 600.' },
    goalBy: { type: 'string', description: 'When the goal should be met, YYYY-MM-DD (defaults to the launch date).' },
    launchAt: { type: 'string', description: 'Launch day, YYYY-MM-DD.' },
    startAt: { type: 'string', description: 'First day of the campaign, YYYY-MM-DD.' },
    endAt: { type: 'string', description: 'Last day of the campaign, YYYY-MM-DD.' },
    budget: { type: 'number', description: 'The whole budget in dollars; replaces the current budget.' },
    budgetChange: {
      type: 'number',
      description: 'Dollars to add to the current budget (negative to cut it). The campaign does the sum.',
    },
    id: { type: 'string', description: "Asset id, e.g. 'as-3'." },
    title: {
      type: 'string',
      description: "The asset's name, e.g. 'Launch-day email'. Also finds an asset when no id is given.",
    },
    channel: {
      type: 'string',
      description: 'email, instagram, facebook, linkedin, bluesky, x, tiktok, youtube, website, ads, print, press, event, or other.',
    },
    kind: {
      type: 'string',
      description: 'post, email, ad, landing-page, video, graphic, print, press-release, event, or other.',
    },
    goesOutAt: { type: 'string', description: 'The day the asset goes out, YYYY-MM-DD.' },
    shiftDays: {
      type: 'number',
      description: "Move the asset's date by this many days (2 = two days later, -1 = a day earlier).",
    },
    owner: { type: 'string', description: 'Who makes or sends it.' },
    status: { type: 'string', description: 'Asset stage: idea, draft, approved, scheduled, or live.' },
    note: { type: 'string', description: 'What happened, in the person’s words.' },
    day: { type: 'string', description: 'The day the numbers or the spend are for, YYYY-MM-DD (default today).' },
    reach: { type: 'number', description: 'People reached: opens, views or impressions.' },
    clicks: { type: 'number', description: 'Clicks through.' },
    conversions: { type: 'number', description: "What the goal counts (preorders, signups) on that day for that asset." },
    amount: { type: 'number', description: 'Dollars spent, e.g. 250 or 249.99.' },
    withinDays: { type: 'number', description: 'How many days ahead the calendar covers (default 14).' },
  },
  outputs: {
    daysToLaunch: { type: 'number', description: 'Days until launch; negative once launched, 0 when no date is set.' },
    assets: { type: 'number', description: 'Assets in the campaign.' },
    ready: { type: 'number', description: 'Assets approved, scheduled or live.' },
    budget: { type: 'number', description: 'The budget, in dollars.' },
    spent: { type: 'number', description: 'Spent so far, in dollars.' },
    conversions: { type: 'number', description: 'Goal results so far.' },
    summary: { type: 'string', description: 'What changed, then the campaign picture; or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── campaign-rules-start ──
// Pure derivations: local calendar days, money in integer cents, the newest
// figures per asset and day, and the campaign picture the crew reads. Kept
// self-contained between these sentinels so tests execute the shipped bytes.
var DAY_MS = 86400000;
var STAGES = ['idea', 'draft', 'approved', 'scheduled', 'live'];
var READY = ['approved', 'scheduled', 'live'];
var CHANNELS = ['email', 'instagram', 'facebook', 'linkedin', 'bluesky', 'x', 'tiktok', 'youtube', 'website', 'ads', 'print', 'press', 'event', 'other'];
var CHANNEL_ALIASES = {
  newsletter: 'email', mail: 'email', 'e-mail': 'email', twitter: 'x', web: 'website', site: 'website', blog: 'website',
  'landing page': 'website', ad: 'ads', paid: 'ads', 'paid ads': 'ads', 'google ads': 'ads', 'meta ads': 'ads',
  'instagram ads': 'ads', 'facebook ads': 'ads', poster: 'print', flyer: 'print', pr: 'press', 'press release': 'press',
  ig: 'instagram', insta: 'instagram', fb: 'facebook',
};
var KINDS = ['post', 'email', 'ad', 'landing-page', 'video', 'graphic', 'print', 'press-release', 'event', 'other'];
var WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var STOP = ['the', 'and', 'our', 'for', 'with', 'from', 'this', 'that', 'asset'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function addDays(day, n) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
// YYYY-MM-DD, or today/tomorrow/yesterday, or a weekday ('friday' is the next one, 'last tuesday' the one before).
function normalizeDate(text, nowMs) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  var lower = raw.toLowerCase();
  var today = localDay(nowMs);
  if (lower === 'today') return today;
  if (lower === 'tomorrow') return addDays(today, 1);
  if (lower === 'yesterday') return addDays(today, -1);
  var m = lower.match(/^(next |this |last )?(sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
  if (m) {
    var target = WEEKDAYS.map(function (w) { return w.toLowerCase(); }).indexOf(m[2]);
    var dow = new Date(today + 'T12:00:00').getDay();
    if (m[1] === 'last ') return addDays(today, -(((dow - target + 6) % 7) + 1));
    return addDays(today, ((target - dow + 6) % 7) + 1);
  }
  var parsed = Date.parse(raw);
  if (!isFinite(parsed)) return null;
  if (/\d{4}/.test(raw)) return localDay(parsed);
  // 'Nov 20' parses into some default year: take this year's, or next year's once it is well past.
  var d = new Date(parsed);
  var year = new Date(nowMs).getFullYear();
  var guess = year + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
  return daysLeft(guess, nowMs) < -60 ? year + 1 + guess.slice(4) : guess;
}
function monthDay(day) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  return MONTHS[d.getMonth()] + ' ' + d.getDate();
}
function weekday(day) {
  return WEEKDAYS[new Date(String(day).slice(0, 10) + 'T12:00:00').getDay()];
}
// A day as a person says it, weekday included so 'how did Tuesday do' finds it:
// 'yesterday, Tuesday (Nov 3)', 'Tuesday (Oct 27)', 'last Tuesday (Oct 20)', 'Fri Nov 6'.
function dayLabel(day, nowMs) {
  var d = daysLeft(day, nowMs);
  if (d === 0) return 'today, ' + weekday(day) + ' (' + monthDay(day) + ')';
  if (d === -1) return 'yesterday, ' + weekday(day) + ' (' + monthDay(day) + ')';
  if (d === 1) return 'tomorrow, ' + weekday(day) + ' (' + monthDay(day) + ')';
  if (d < -1 && d > -7) return weekday(day) + ' (' + monthDay(day) + ')';
  if (d === -7) return 'last ' + weekday(day) + ' (' + monthDay(day) + ')';
  return weekday(day).slice(0, 3) + ' ' + monthDay(day);
}
function inDays(d) {
  if (d < 0) return -d + (d === -1 ? ' day ago' : ' days ago');
  if (d === 0) return 'today';
  return 'in ' + d + (d === 1 ? ' day' : ' days');
}
function toCents(value) {
  if (typeof value === 'number') return isFinite(value) ? Math.round(value * 100) : null;
  var text = String(value == null ? '' : value).replace(/[$,\s]/g, '').replace(/^usd/i, '');
  if (!/^[-+]?\d+(\.\d+)?$/.test(text)) return null;
  return Math.round(Number(text) * 100);
}
function money(cents) {
  var abs = Math.abs(Math.round(cents));
  var whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (cents < 0 ? '-' : '') + '$' + whole + '.' + pad(abs % 100);
}
function count(n) {
  return String(Math.round(n || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}
function wholeNumber(value) {
  var n = typeof value === 'string' ? Number(String(value).replace(/,/g, '')) : value;
  return typeof n === 'number' && isFinite(n) && n >= 0 ? Math.round(n) : null;
}
function channelOf(text) {
  var key = String(text || '').trim().toLowerCase();
  if (!key) return null;
  if (CHANNELS.indexOf(key) >= 0) return key;
  return CHANNEL_ALIASES[key] || 'other';
}
function stem(word) {
  return word.replace(/(ing|ed|es|s|e)$/, '');
}
function words(text) {
  return (String(text || '').toLowerCase().match(/[a-z0-9]+/g) || []).map(stem).filter(function (w) {
    return w.length > 2 && STOP.indexOf(w) < 0;
  });
}
// The record a person means: its id, its exact title, a unique part of its
// title, or the title sharing the most words with what they wrote.
function findRecord(records, key) {
  var text = String(key || '').trim();
  if (!text) return { record: null, matches: [] };
  var lower = text.toLowerCase();
  var titleOf = function (r) { return String((r.fields && r.fields.title) || '').toLowerCase(); };
  var byId = records.filter(function (r) { return String(r.id).toLowerCase() === lower; });
  if (byId.length) return { record: byId[0], matches: byId };
  var exact = records.filter(function (r) { return titleOf(r) === lower; });
  if (exact.length === 1) return { record: exact[0], matches: exact };
  var partial = records.filter(function (r) { return titleOf(r).indexOf(lower) >= 0; });
  if (partial.length === 1) return { record: partial[0], matches: partial };
  if (partial.length > 1) return { record: null, matches: partial };
  var want = words(text);
  var best = 0;
  var hits = [];
  records.forEach(function (r) {
    var have = words(titleOf(r));
    var score = want.filter(function (w) { return have.indexOf(w) >= 0; }).length;
    if (score > best) { best = score; hits = [r]; } else if (score === best && score > 0) hits.push(r);
  });
  return { record: hits.length === 1 ? hits[0] : null, matches: hits };
}
// The newest figures per asset and day: a second report for the same day replaces the first.
function latestResults(events) {
  var byKey = {};
  var order = [];
  events.forEach(function (e) {
    if (e.kind !== 'result' || !e.data || !e.data.day) return;
    var key = (e.data.assetId || '-') + '@' + e.data.day;
    if (!(key in byKey)) order.push(key);
    byKey[key] = e;
  });
  return order.map(function (k) { return byKey[k]; });
}
function sumResults(list) {
  var t = { reach: 0, clicks: 0, conversions: 0 };
  list.forEach(function (e) {
    t.reach += Number(e.data.reach) || 0;
    t.clicks += Number(e.data.clicks) || 0;
    t.conversions += Number(e.data.conversions) || 0;
  });
  return t;
}
function spendOf(events) {
  var total = 0;
  var byChannel = {};
  events.forEach(function (e) {
    if (e.kind !== 'spend' || !e.data) return;
    var cents = Number(e.data.amountCents) || 0;
    total += cents;
    var ch = e.data.channel || 'other';
    byChannel[ch] = (byChannel[ch] || 0) + cents;
  });
  return { totalCents: total, byChannel: byChannel };
}
function figures(t, metric) {
  return count(t.conversions) + ' ' + metric + ', ' + count(t.reach) + ' reach, ' + count(t.clicks) + ' clicks';
}
function assetLine(r, results, metric, nowMs) {
  var f = r.fields || {};
  var mine = results.filter(function (e) { return e.data.assetId === r.id; });
  return (
    f.title + ' (' + r.id + ', ' + (f.channel || 'other') + ', ' + r.status +
    (f.goesOutAt ? ', ' + dayLabel(f.goesOutAt, nowMs) : ', no date yet') +
    ', owner ' + (f.owner || 'unassigned') + ')' +
    (mine.length ? ': ' + figures(sumResults(mine), metric) : '')
  );
}
function picture(campaign, records, events, nowMs, withinDays, focusDay) {
  var metric = campaign.goalMetric || 'conversions';
  var results = latestResults(events);
  var totals = sumResults(results);
  var spend = spendOf(events);
  var today = localDay(nowMs);
  var titleOf = function (id) {
    var r = records.find(function (x) { return x.id === id; });
    return r ? r.fields.title + ' (' + id + ')' : id;
  };
  var dayLine = function (day) {
    var list = results.filter(function (e) { return e.data.day === day; });
    if (!list.length) return dayLabel(day, nowMs) + ': no results logged';
    return dayLabel(day, nowMs) + ': ' + figures(sumResults(list), metric) + ' (from ' + list.map(function (e) {
      return titleOf(e.data.assetId) + ' ' + count(e.data.conversions);
    }).join(', ') + ')';
  };
  var parts = [];
  if (focusDay) parts.push('Results on ' + dayLine(focusDay) + '.');
  var launchIn = campaign.launchAt ? daysLeft(campaign.launchAt, nowMs) : null;
  if (!campaign.name && !campaign.goal) {
    parts.push('No campaign set yet: call set_campaign with its name, goal, launch date and budget.');
  } else {
    parts.push(
      (campaign.name || 'The campaign') + (campaign.goal ? '. Goal: ' + campaign.goal : '') + '.' +
      (campaign.audience ? ' Audience: ' + campaign.audience + '.' : '') +
      (campaign.launchAt ? ' Launch ' + dayLabel(campaign.launchAt, nowMs) + ', ' + inDays(launchIn) + '.' : ' No launch date yet.') +
      (campaign.endAt ? ' Runs until ' + dayLabel(campaign.endAt, nowMs) + '.' : ''),
    );
  }
  var target = Number(campaign.goalTarget) || 0;
  parts.push(
    'Results so far: ' + (target ? count(totals.conversions) + ' of ' + count(target) + ' ' + metric + ' (' + Math.round((totals.conversions / target) * 100) + '%)' : count(totals.conversions) + ' ' + metric) +
    ', ' + count(totals.reach) + ' reach, ' + count(totals.clicks) + ' clicks.',
  );
  var goalBy = campaign.goalBy || campaign.launchAt || campaign.endAt;
  if (target && goalBy) {
    var toGo = target - totals.conversions;
    var daysToGoal = daysLeft(goalBy, nowMs);
    var firstDay = results.map(function (e) { return e.data.day; }).sort()[0];
    var start = campaign.startAt && campaign.startAt <= today ? campaign.startAt : firstDay;
    var elapsed = start ? Math.max(1, -daysLeft(start, nowMs) + 1) : 0;
    if (toGo <= 0) parts.push('Goal met.');
    else if (daysToGoal < 0) parts.push('The goal date passed ' + inDays(daysToGoal) + ' with ' + count(toGo) + ' ' + metric + ' still to go.');
    else {
      var pace = elapsed ? Math.round(totals.conversions / elapsed) : 0;
      var need = Math.ceil(toGo / Math.max(1, daysToGoal));
      parts.push(
        'Pace: ' + count(totals.conversions) + ' ' + metric + (elapsed ? ' in ' + elapsed + (elapsed === 1 ? ' day' : ' days') + ', about ' + count(pace) + ' a day' : '') +
        '; ' + count(toGo) + ' to go by ' + dayLabel(goalBy, nowMs) + ' needs ' + count(need) + ' a day. ' +
        (pace >= need ? 'On pace.' : 'Behind pace.'),
      );
    }
  }
  var days = [];
  for (var i = 0; i <= 7; i++) days.push(addDays(today, -i));
  var logged = days.filter(function (day) { return results.some(function (e) { return e.data.day === day; }); });
  parts.push(
    logged.length
      ? 'Results by day, last 8 days, newest first: ' + logged.map(dayLine).join(' | ') + '. Other days have no results logged.'
      : 'No results logged in the last 8 days.',
  );
  var byDay = {};
  results.forEach(function (e) { byDay[e.data.day] = (byDay[e.data.day] || 0) + (Number(e.data.conversions) || 0); });
  var bestDay = Object.keys(byDay).sort(function (a, b) { return byDay[b] - byDay[a] || b.localeCompare(a); })[0];
  if (bestDay) parts.push('Best day so far: ' + dayLabel(bestDay, nowMs) + ', ' + count(byDay[bestDay]) + ' ' + metric + '.');
  var budget = Number(campaign.budgetCents) || 0;
  var channels = Object.keys(spend.byChannel).sort(function (a, b) { return spend.byChannel[b] - spend.byChannel[a]; });
  parts.push(
    (budget
      ? 'Budget ' + money(budget) + ': spent ' + money(spend.totalCents) + ' (' + Math.round((spend.totalCents / budget) * 100) + '%), ' +
        (budget - spend.totalCents >= 0 ? money(budget - spend.totalCents) + ' left.' : money(spend.totalCents - budget) + ' over.')
      : 'No budget set; spent ' + money(spend.totalCents) + '.') +
    (channels.length ? ' Spent by channel: ' + channels.map(function (c) { return c + ' ' + money(spend.byChannel[c]); }).join(', ') + '.' : ''),
  );
  var dated = records.filter(function (r) { return r.fields && r.fields.goesOutAt; });
  var overdue = dated.filter(function (r) { return r.status !== 'live' && daysLeft(r.fields.goesOutAt, nowMs) < 0; });
  var upcoming = dated.filter(function (r) {
    var d = daysLeft(r.fields.goesOutAt, nowMs);
    return d >= 0 && d <= withinDays;
  });
  var byDate = function (a, b) { return String(a.fields.goesOutAt).localeCompare(String(b.fields.goesOutAt)); };
  overdue.sort(byDate);
  upcoming.sort(byDate);
  // One list, late items first: a question about the coming days must see what slipped.
  var calendar = overdue.concat(upcoming);
  parts.push(
    calendar.length
      ? 'Calendar, next ' + withinDays + ' days, late items first: ' + calendar.map(function (r) {
          var d = daysLeft(r.fields.goesOutAt, nowMs);
          return assetLine(r, [], metric, nowMs) + (d < 0 && r.status !== 'live' ? ', ' + -d + (d === -1 ? ' day late' : ' days late') : '');
        }).join(' | ') + '.'
      : 'Nothing on the calendar in the next ' + withinDays + ' days.',
  );
  var later = dated.filter(function (r) { return daysLeft(r.fields.goesOutAt, nowMs) > withinDays; }).sort(byDate);
  if (later.length) parts.push('Next after that: ' + later[0].fields.title + ' (' + later[0].id + ') on ' + dayLabel(later[0].fields.goesOutAt, nowMs) + '.');
  var undated = records.filter(function (r) { return !r.fields || !r.fields.goesOutAt; });
  if (undated.length) parts.push('Not dated yet: ' + undated.map(function (r) { return r.fields.title + ' (' + r.id + ', ' + r.status + ')'; }).join(', ') + '.');
  var stageCounts = STAGES.map(function (s) {
    var n = records.filter(function (r) { return r.status === s; }).length;
    return n ? n + ' ' + s : '';
  }).filter(Boolean);
  parts.push(records.length ? 'Assets: ' + records.length + ' (' + stageCounts.join(', ') + ').' : 'No assets yet.');
  return {
    daysToLaunch: launchIn === null ? 0 : launchIn,
    ready: records.filter(function (r) { return READY.indexOf(r.status) >= 0; }).length,
    spentCents: spend.totalCents,
    conversions: totals.conversions,
    summary: parts.join(' '),
  };
}
// ── campaign-rules-end ──

interface Campaign {
  version: number;
  name: string;
  goal: string;
  audience: string;
  goalMetric: string;
  goalTarget: number;
  goalBy: string;
  launchAt: string;
  startAt: string;
  endAt: string;
  budgetCents: number;
  updatedAt?: string;
}

const CAMPAIGN_FILE = 'campaign.json';
const assets = rosterStore(gezel.fs, 'assets.json', {
  stages: ['idea', 'draft', 'approved', 'scheduled', 'live'],
  idPrefix: 'as',
});
const results = logStore(gezel.fs, 'results.json');

async function loadCampaign(): Promise<Campaign> {
  const blank: Campaign = {
    version: 1,
    name: '',
    goal: '',
    audience: '',
    goalMetric: '',
    goalTarget: 0,
    goalBy: '',
    launchAt: '',
    startAt: '',
    endAt: '',
    budgetCents: 0,
  };
  let raw: string;
  try {
    raw = await gezel.fs.read(CAMPAIGN_FILE);
  } catch {
    return blank;
  }
  let parsed: Partial<Campaign>;
  try {
    parsed = JSON.parse(raw) as Partial<Campaign>;
  } catch {
    throw new Error('campaign.json is not valid JSON. Fix or remove it; it will not be overwritten.');
  }
  return {
    ...blank,
    ...parsed,
    version: 1,
    goalTarget: Number(parsed.goalTarget) || 0,
    budgetCents: Number(parsed.budgetCents) || 0,
  };
}

async function saveCampaign(campaign: Campaign): Promise<void> {
  campaign.updatedAt = new Date().toISOString();
  await gezel.fs.write(CAMPAIGN_FILE, `${JSON.stringify(campaign, null, 2)}\n`);
}

async function resolve() {
  const all = await assets.list();
  const keys = [input.id, input.title].filter((k): k is string => typeof k === 'string' && k.trim() !== '');
  for (const key of keys) {
    const found = findRecord(all, key);
    if (found.record) return found.record;
    if (found.matches.length > 1) {
      throw new Error(
        "More than one asset matches '" + key + "': " + found.matches.map((r) => r.id + ' ' + String(r.fields.title)).join(', ') + '. Pass id.',
      );
    }
  }
  const known = all.map((r) => r.id + ' ' + String(r.fields.title)).join(', ') || 'none yet';
  throw new Error(
    (keys.length ? "No asset matches '" + keys.join("' or '") + "'. " : "Pass 'id' (e.g. 'as-3') or the asset's 'title'. ") + 'Assets: ' + known + '.',
  );
}

function dateInput(value: string | undefined, label: string): string | null {
  if (value === undefined || String(value).trim() === '') return null;
  const day = normalizeDate(value, Date.now());
  if (!day) throw new Error(label + " must be a date, e.g. '2026-12-01'.");
  return day;
}

const now = Date.now();
const today = localDay(now);
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 14;
let note = '';
let focusDay: string | null = null;

if (input.action === 'set_campaign') {
  const campaign = await loadCampaign();
  const changed: string[] = [];
  for (const key of ['name', 'goal', 'audience', 'goalMetric'] as const) {
    const value = input[key];
    if (typeof value === 'string' && value.trim()) {
      campaign[key] = value.trim();
      changed.push(key === 'goalMetric' ? 'what the goal counts' : key);
    }
  }
  for (const [key, label] of [
    ['launchAt', 'launch date'],
    ['startAt', 'start date'],
    ['endAt', 'end date'],
    ['goalBy', 'goal date'],
  ] as const) {
    const day = dateInput(input[key], key);
    if (day) {
      campaign[key] = day;
      changed.push(label);
    }
  }
  if (input.goalTarget !== undefined) {
    const target = wholeNumber(input.goalTarget);
    if (target === null) throw new Error('goalTarget must be a whole number, e.g. 600.');
    campaign.goalTarget = target;
    changed.push('goal number');
  }
  if (input.budget !== undefined) {
    const cents = toCents(input.budget);
    if (cents === null || cents < 0) throw new Error('budget must be an amount in dollars, e.g. 2400.');
    campaign.budgetCents = cents;
    changed.push('budget (' + money(cents) + ')');
  }
  if (input.budgetChange !== undefined) {
    const cents = toCents(input.budgetChange);
    if (cents === null || cents === 0) throw new Error('budgetChange must be dollars to add, e.g. 500 (or -200 to cut).');
    const before = campaign.budgetCents;
    campaign.budgetCents = Math.max(0, before + cents);
    changed.push('budget ' + (cents > 0 ? 'raised by ' + money(cents) : 'cut by ' + money(-cents)) + ' from ' + money(before) + ' to ' + money(campaign.budgetCents));
  }
  if (!changed.length) {
    throw new Error('set_campaign needs at least one of name, goal, audience, goalMetric, goalTarget, launchAt, startAt, endAt, goalBy, budget, or budgetChange.');
  }
  await saveCampaign(campaign);
  note = 'Campaign updated: ' + changed.join(', ') + '.';
} else if (input.action === 'add_asset') {
  if (!input.title || !input.title.trim()) throw new Error("add_asset needs 'title'.");
  const goesOutAt = dateInput(input.goesOutAt, 'goesOutAt');
  const channel = channelOf(input.channel);
  const kind = KINDS.includes(String(input.kind)) ? String(input.kind) : undefined;
  const status = input.status ? String(input.status).toLowerCase() : undefined;
  if (status && !STAGES.includes(status)) throw new Error("status must be one of idea, draft, approved, scheduled, live.");
  const wanted = input.title.trim().toLowerCase();
  const existing = (await assets.list()).find((r) => String(r.fields.title ?? '').toLowerCase() === wanted);
  const fields: Record<string, unknown> = {
    ...(goesOutAt ? { goesOutAt } : {}),
    ...(channel ? { channel } : {}),
    ...(kind ? { kind } : {}),
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (existing) {
    await assets.update(existing.id, { fields });
    if (status && status !== existing.status) await assets.transition(existing.id, status, { note: 'Updated from the plan' });
    note = 'Updated ' + String(existing.fields.title) + ' (' + existing.id + ').';
  } else {
    const record = await assets.add({
      status: status ?? 'idea',
      fields: { title: input.title.trim(), channel: channel ?? 'other', kind: kind ?? 'post', ...fields },
    });
    note = 'Added ' + record.id + ' ' + String(record.fields.title) + (goesOutAt ? ' on ' + dayLabel(goesOutAt, now) : '') + '.';
  }
} else if (input.action === 'move_asset') {
  const record = await resolve();
  const fields: Record<string, unknown> = {};
  const goesOutAt = dateInput(input.goesOutAt, 'goesOutAt');
  if (goesOutAt) fields.goesOutAt = goesOutAt;
  if (typeof input.shiftDays === 'number' && input.shiftDays !== 0) {
    const from = goesOutAt ?? (typeof record.fields.goesOutAt === 'string' ? record.fields.goesOutAt : null);
    if (!from) throw new Error(String(record.fields.title) + " has no date yet; pass goesOutAt instead of shiftDays.");
    fields.goesOutAt = addDays(from, Math.round(input.shiftDays));
  }
  if (input.owner) fields.owner = input.owner.trim();
  if (input.channel) fields.channel = channelOf(input.channel);
  const status = input.status ? String(input.status).toLowerCase() : undefined;
  if (status && !STAGES.includes(status)) throw new Error("status must be one of idea, draft, approved, scheduled, live.");
  if (!Object.keys(fields).length && !status && !input.note) {
    throw new Error('move_asset needs status, goesOutAt, shiftDays, owner, channel, or note.');
  }
  if (Object.keys(fields).length) await assets.update(record.id, { fields });
  if (status && status !== record.status) await assets.transition(record.id, status, input.note ? { note: input.note } : {});
  else if (input.note) await assets.update(record.id, { note: input.note });
  note =
    String(record.fields.title) + ' (' + record.id + ')' +
    (status && status !== record.status ? ' moved from ' + record.status + ' to ' + status : ' updated') +
    (fields.goesOutAt ? ', now going out ' + dayLabel(String(fields.goesOutAt), now) : '') +
    (fields.owner ? ', owner ' + String(fields.owner) : '') + '.';
} else if (input.action === 'log_result') {
  const record = await resolve();
  const day = dateInput(input.day, 'day') ?? today;
  const given: Record<string, number> = {};
  for (const key of ['reach', 'clicks', 'conversions'] as const) {
    if (input[key] === undefined) continue;
    const n = wholeNumber(input[key]);
    if (n === null) throw new Error(key + ' must be a whole number of 0 or more.');
    given[key] = n;
  }
  if (!Object.keys(given).length) throw new Error('log_result needs at least one of reach, clicks, or conversions.');
  const prior = latestResults(await results.list({ kind: 'result' })).find((e) => e.data.assetId === record.id && e.data.day === day);
  const data = { ...(prior ? prior.data : {}), assetId: record.id, day, channel: record.fields.channel ?? 'other', ...given };
  await results.append({ kind: 'result', note: input.note ?? 'Results for ' + String(record.fields.title) + '.', data });
  if (record.status !== 'live') await assets.transition(record.id, 'live', { note: 'Results logged' });
  const campaign = await loadCampaign();
  note =
    'Logged ' + dayLabel(day, now) + ' for ' + String(record.fields.title) + ' (' + record.id + '): ' +
    figures({ reach: Number(data.reach) || 0, clicks: Number(data.clicks) || 0, conversions: Number(data.conversions) || 0 }, campaign.goalMetric || 'conversions') +
    (prior ? ', replacing the earlier figures for that day' : '') + '.';
  focusDay = day;
} else if (input.action === 'log_spend') {
  const cents = toCents(input.amount);
  if (cents === null || cents <= 0) throw new Error('log_spend needs amount in dollars, e.g. 250.');
  const record = input.id || input.title ? await resolve() : null;
  const channel = channelOf(input.channel) ?? (record ? String(record.fields.channel ?? 'other') : 'other');
  const day = dateInput(input.day, 'day') ?? today;
  await results.append({
    kind: 'spend',
    note: input.note ?? 'Spent ' + money(cents) + ' on ' + channel + '.',
    data: { day, channel, amountCents: cents, ...(record ? { assetId: record.id } : {}) },
  });
  note = 'Logged ' + money(cents) + ' spent on ' + channel + (record ? ' for ' + String(record.fields.title) : '') + ' ' + dayLabel(day, now) + '.';
} else if (input.action === 'status') {
  if (input.day) focusDay = dateInput(input.day, 'day');
} else if (input.action !== 'list') {
  throw new Error(
    "Unknown action '" + input.action + "'. Use status, set_campaign, add_asset, move_asset, log_result, log_spend, or list.",
  );
}

const campaign = await loadCampaign();
const records = await assets.list();
const events = await results.list();
const view = picture(campaign, records, events, now, withinDays, focusDay);
const latest = latestResults(events);
const metric = campaign.goalMetric || 'conversions';

gezel.output({
  daysToLaunch: view.daysToLaunch,
  assets: records.length,
  ready: view.ready,
  budget: campaign.budgetCents / 100,
  spent: view.spentCents / 100,
  conversions: view.conversions,
  summary:
    input.action === 'list'
      ? records
          .slice()
          .sort((a, b) => String(a.fields.goesOutAt ?? '9999').localeCompare(String(b.fields.goesOutAt ?? '9999')))
          .map((r) => assetLine(r, latest, metric, now))
          .join('\n') || 'No assets yet.'
      : (note ? note + ' ' : '') + view.summary,
});

